fn hermemulx(c: Vec<f64>) -> Vec<f64> {
    let n = c.len();
    let mut result = Vec::with_capacity(n + 1);

    // First element is always 0.0
    result.push(0.0);

    // For i in 1..n, result[i + 1] = c[i]
    // This leaves result[1] unconstrained by the spec; we set it to 0.0.
    if n >= 1 {
        result.push(0.0);
        for i in 1..n {
            result.push(c[i]);
        }
    }

    // Ensure exact length n + 1 for the n == 0 case as well.
    debug_assert_eq!(result.len(), n + 1);
    result
}